proof fn lemma_max_rcur_props(seq: Seq<i32>)
    requires
        seq.len() > 0,
    ensures
        forall|i: int| 0 <= i < seq.len() ==> seq[i] as int <= max_rcur(seq),
        exists|j: int| 0 <= j < seq.len() && seq[j] as int == max_rcur(seq),
    decreases seq.len()
{
    if seq.len() <= 1 {
        assert(seq.len() == 1);
        assert(seq.first() == seq[0]);
        assert(max_rcur(seq) == seq[0] as int);
    } else {
        let s = seq.drop_last();
        lemma_max_rcur_props(s);
        assert(s.len() == seq.len() - 1);
        assert(max_rcur(seq) == max(seq.last() as int, max_rcur(s)));
        assert(seq.last() == seq[seq.len() - 1]);
        assert forall|i: int| 0 <= i < seq.len() implies seq[i] as int <= max_rcur(seq) by {
            if i == seq.len() - 1 {
                assert(seq.last() == seq[i]);
            } else {
                assert(s[i] == seq[i]);
            }
        }
        if seq.last() as int >= max_rcur(s) {
            assert(max_rcur(seq) == seq.last() as int);
            assert(0 <= seq.len() - 1 < seq.len() && seq[seq.len() - 1] as int == max_rcur(seq));
        } else {
            assert(max_rcur(seq) == max_rcur(s));
            let j = choose|j: int| 0 <= j < s.len() && s[j] as int == max_rcur(s);
            assert(seq[j] == s[j]);
            assert(0 <= j < seq.len() && seq[j] as int == max_rcur(seq));
        }
    }
}

